// ─── Helpers ──────────────────────────────────────────────────────────────────
const fmt = n => `PKR ${n.toLocaleString()}`;
const ini = n => n.split(" ").map(w=>w[0]).join("").toUpperCase().slice(0,2);
const COLORS = ["#E8700A","#2D6BE4","#7C3AED","#00C878","#F0A500","#E84040"];
const avc = name => COLORS[name.split("").reduce((a,c)=>a+c.charCodeAt(0),0)%COLORS.length];

function genStudentId(name) {
  const hash = name.split("").reduce((a,c)=>a+c.charCodeAt(0),0);
  return `GB-${String(hash % 9000 + 1000)}-KHI`;
}

function genBizId(name) {
  const hash = name.split("").reduce((a,c)=>a+c.charCodeAt(0),0);
  return `GB-BIZ-${String(hash % 9000 + 1000)}`;
}

function getTier(hires) {
  if (hires >= 5) return { name:"Gold", icon:"🥇", color: C.gold };
  if (hires >= 2) return { name:"Silver", icon:"🥈", color: "#A8B8C8" };
  return { name:"Rising Star", icon:"⭐", color: C.orange };
}

function getProfileStrength(user) {
  let score = 20; // base
  if (user.name) score += 15;
  if (user.skills && user.skills.length > 0) score += 25;
  if (user.idCard) score += 20;
  if (user.bio) score += 10;
  if (user.payMethod) score += 10;
  return Math.min(score, 100);
}

// Calculate business trust score (0-100)
function getBizTrustScore(biz) {
  let score = 0;
  if (biz.bname) score += 10;
  if (biz.email) score += 10;
  if (biz.phone) score += 10;
  if (biz.industry) score += 10;
  if (biz.size) score += 5;
  if (biz.foundedYear) score += 5;
  if (biz.address) score += 10;
  if (biz.area) score += 5;
  if (biz.website) score += 5;
  if (biz.ntn) score += 15;     // NTN/registration is major trust signal
  if (biz.regDoc) score += 15;  // Registration document upload
  return Math.min(score, 100);
}

// Get trust level label
function getBizTrustLevel(score) {
  if (score >= 80) return { label:"Highly Verified", color: C.green, icon:"🛡️" };
  if (score >= 60) return { label:"Verified", color: C.blueL, icon:"✓" };
  if (score >= 40) return { label:"Basic Info", color: C.gold, icon:"⚠️" };
  return { label:"Unverified", color: C.red, icon:"⚠️" };
}

