// ─── Upload Zone ──────────────────────────────────────────────────────────────
function UploadZone({onUpload, uploaded, label="Upload ID Card", icon="🪪", helper="JPG, PNG or PDF · Tap or drag to upload"}){
  const [drag, setDrag] = useState(false);
  const inputRef = useRef();

  const handleFile = (file) => {
    if(!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      onUpload({ name: file.name, type: file.type, data: e.target.result, size: file.size });
    };
    reader.readAsDataURL(file);
  };

  return(
    <div>
      {uploaded ? (
        <div style={{background:"rgba(0,200,120,0.08)",border:`1.5px solid ${C.green}`,
          borderRadius:14,padding:"14px 16px",display:"flex",alignItems:"center",gap:12}}>
          <div style={{fontSize:28}}>{uploaded.type?.includes("pdf")?"📄":icon}</div>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontWeight:700,fontSize:13,color:C.green}}>✓ Uploaded Successfully</div>
            <div style={{color:C.sub,fontSize:12,marginTop:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{uploaded.name}</div>
          </div>
          <button onClick={()=>onUpload(null)} style={{background:"none",color:C.sub,fontSize:18}}>✕</button>
        </div>
      ):(
        <div
          className={`upload-zone${drag?" drag":""}`}
          onDragOver={e=>{e.preventDefault();setDrag(true);}}
          onDragLeave={()=>setDrag(false)}
          onDrop={e=>{e.preventDefault();setDrag(false);handleFile(e.dataTransfer.files[0]);}}
          onClick={()=>inputRef.current?.click()}>
          <input ref={inputRef} type="file" accept=".jpg,.jpeg,.png,.pdf" style={{display:"none"}}
            onChange={e=>handleFile(e.target.files[0])}/>
          <div style={{fontSize:32,marginBottom:8}}>{icon}</div>
          <div style={{fontWeight:700,fontSize:14,color:C.text,marginBottom:4}}>{label}</div>
          <div style={{fontSize:12,color:C.sub}}>{helper}</div>
        </div>
      )}
    </div>
  );
}

